      "keystrokes": "cd /app && ./reversed 2>/dev/null && cmp image.ppm /tmp/orig.ppm; echo "exit=$?"
",
      "duration": 2.0
    },
    {
      "keystrokes": "head -20 image.ppm && echo "---" && head -20 /tmp/orig.ppm
",
      "duration": 0.1
    },
    {
      "keystrokes": "cat mystery.c | gzip | wc
",
      "duration": 0.1
    }
  ]
